use vstd::prelude::*;
use vstd::string::*;

verus! {

spec fn is_ascii_digit_char(c: char) -> bool {
    '0' <= c && c <= '9'
}

fn is_ascii_digit(c: char) -> (b: bool)
    ensures
        b == is_ascii_digit_char(c)
{
    let b = c >= '0' && c <= '9';
    b
}

spec fn all_digits_spec(s: String) -> bool {
    forall|i: int| 0 <= i && i < s.len() ==> is_ascii_digit_char(s[i])
}

fn all_digits(s: String) -> (b: bool)
    ensures
        b == all_digits_spec(s)
{
    let mut i: usize = 0;
    let len = s.len();
    
    while i < len
        invariant
            0 <= i <= len,
            forall|j: int| 0 <= j && j < i ==> is_ascii_digit_char(s[j]),
        decreases len - i,
    {
        let c = s[i];
        let is_digit = is_ascii_digit(c);
        if !is_digit {
            return false;
        }
        i = i + 1;
    }
    
    true
}

}
